// Threads core (m.thread, spec v1.4+: MSC3440 relations, MSC3771 threaded receipts, MSC3773 per-thread counts).
// Pure: no SDK, no DOM. The desktop's crates/widgets/src/threads.rs is a line-for-line port; both replay
// testvectors/threads/vectors.json (a byte-identical copy in both repos, generated by an independent reference:
// tools/threads/oracle.py). docs/THREADS.md has the design.

export const THREAD_REL = "m.thread";
export const THREAD_REL_UNSTABLE = "io.element.thread";
export const SEP = " · ";

type Json = any;

/** The thread root an event's content puts it in, or "". Reads the stable and the unstable (old Element) name. */
export function threadOf(content: Json): string {
  if (!content || typeof content !== "object" || Array.isArray(content)) return "";
  const rel = content["m.relates_to"];
  if (!rel || typeof rel !== "object" || Array.isArray(rel)) return "";
  if (rel.rel_type !== THREAD_REL && rel.rel_type !== THREAD_REL_UNSTABLE) return "";
  return typeof rel.event_id === "string" ? rel.event_id : "";
}

/** Any other relation (edit, reaction, reference): the event it points at, or "". */
export function relationTarget(content: Json): string {
  if (!content || typeof content !== "object" || Array.isArray(content)) return "";
  const rel = content["m.relates_to"];
  if (!rel || typeof rel !== "object" || Array.isArray(rel) || typeof rel.rel_type !== "string") return "";
  return typeof rel.event_id === "string" ? rel.event_id : "";
}

export interface ThreadEv {
  event_id: string;
  type?: string;
  content: Json;
}

/** Per event (same order): the thread it belongs to ("" = the main timeline). Pass 1: its own m.thread relation.
 *  Pass 2: an edit / reaction / reference of an event in a thread is in that thread (one hop, like the server). */
export function threadIds(events: ThreadEv[]): string[] {
  const direct = new Map<string, string>();
  for (const e of events) direct.set(e.event_id, threadOf(e.content));
  const out: string[] = [];
  for (const e of events) {
    let t = direct.get(e.event_id) ?? "";
    if (t === "") {
      const tgt = relationTarget(e.content);
      if (tgt !== "") t = direct.get(tgt) ?? "";
    }
    out.push(t);
  }
  return out;
}

/** m.relates_to for a reply to `parentId`. A07.3: a parent in a thread keeps the reply in that thread. */
export function replyRelation(parentId: string, parentThread: string): Json {
  if (parentThread !== "") {
    return { rel_type: THREAD_REL, event_id: parentThread, is_falling_back: false, "m.in_reply_to": { event_id: parentId } };
  }
  return { "m.in_reply_to": { event_id: parentId } };
}

/** m.relates_to for a message from the thread composer: the spec's fallback reply to the thread's latest event, so
 *  clients without threads show it as a normal reply. */
export function threadRelation(root: string, latest: string): Json {
  return { rel_type: THREAD_REL, event_id: root, is_falling_back: true, "m.in_reply_to": { event_id: latest !== "" ? latest : root } };
}

export interface ReplyRef {
  id: string;
  sender: string;
  ts: number;
  redacted?: boolean;
}
export interface Bundle {
  count: number;
  latest: { id: string; sender: string; ts: number };
  participated?: boolean;
}
export interface Summary {
  count: number;
  lastId: string;
  lastSender: string;
  lastTs: number;
  repliers: string[];
  mine: boolean;
}

function newer(a: ReplyRef, b: ReplyRef): boolean {
  if (a.ts !== b.ts) return a.ts > b.ts;
  return a.id > b.id;
}

/** The thread's summary from the server's bundled aggregation (unsigned m.relations m.thread) merged with the thread
 *  events seen since. null = no (visible) replies. */
export function summarize(bundle: Bundle | null, seen: ReplyRef[], me: string): Summary | null {
  const live: ReplyRef[] = [];
  const ids = new Set<string>();
  const gone = new Set<string>();
  for (const s of seen) {
    if (s.redacted) {
      gone.add(s.id);
      continue;
    }
    if (ids.has(s.id)) continue;
    ids.add(s.id);
    live.push(s);
  }
  const cands: ReplyRef[] = [...live];
  let count: number;
  let mine: boolean;
  if (bundle) {
    const lat = bundle.latest;
    const extra = live.filter((s) => s.ts > lat.ts && s.id !== lat.id).length;
    // a bundle whose latest reply has been deleted since: that reply no longer counts and never shows
    const base = gone.has(lat.id) ? bundle.count - 1 : bundle.count;
    count = Math.max(base + extra, live.length);
    if (!ids.has(lat.id) && !gone.has(lat.id)) cands.push({ id: lat.id, sender: lat.sender, ts: lat.ts });
    mine = !!bundle.participated;
  } else {
    count = live.length;
    mine = false;
  }
  if (count === 0 || cands.length === 0) return null;
  let last = cands[0];
  for (const c of cands.slice(1)) if (newer(c, last)) last = c;
  const order = [...cands].sort((a, b) => (a.ts !== b.ts ? b.ts - a.ts : a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  const repliers: string[] = [];
  for (const c of order) {
    if (!repliers.includes(c.sender)) repliers.push(c.sender);
    if (repliers.length === 3) break;
  }
  mine = mine || live.some((s) => s.sender === me);
  return { count, lastId: last.id, lastSender: last.sender, lastTs: last.ts, repliers, mine };
}

/** Relative age, integer maths only (no time zone): both apps print the same bytes. */
export function relTime(d: number): string {
  if (d < 60000) return "just now";
  const m = Math.floor(d / 60000);
  if (m < 60) return `${m} min ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h} h ago`;
  const days = Math.floor(h / 24);
  if (days === 1) return "yesterday";
  if (days < 7) return `${days} days ago`;
  if (days < 365) return `${Math.floor(days / 7)} wk ago`;
  return `${Math.floor(days / 365)} yr ago`;
}

export function countText(n: number): string {
  return n === 1 ? "1 reply" : `${n} replies`;
}

/** The line under a thread root: "12 replies · Ana · 5 min ago". */
export function summaryText(count: number, name: string, ts: number, now: number): string {
  return countText(count) + SEP + name + SEP + relTime(now - ts);
}

/** The same for screen readers: "12 replies, last from Ana 5 min ago. Open thread". */
export function summaryLabel(count: number, name: string, ts: number, now: number): string {
  return `${countText(count)}, last from ${name} ${relTime(now - ts)}. Open thread`;
}

export interface MyReceipt {
  eventId: string;
  ts: number;
  /** "" = unthreaded, "main", or a thread root */
  thread: string;
}

/** Unread replies in one thread. `known` = the loaded events {id, ts} (root included); `receipts` = mine: an
 *  unthreaded one or this thread's count, "main" and other threads' don't. A receipt reads up to the ts of the event
 *  it points at; when that event isn't loaded, only this thread's own receipt counts (by its own ts); my own reply
 *  reads everything before it. */
export function threadUnread(root: string, known: { id: string; ts: number }[], replies: ReplyRef[], me: string, receipts: MyReceipt[]): number {
  const tsOf = new Map<string, number>();
  for (const k of known) tsOf.set(k.id, k.ts);
  let mark = 0;
  for (const r of receipts) {
    if (r.thread !== "" && r.thread !== root) continue;
    let t: number;
    if (tsOf.has(r.eventId)) t = tsOf.get(r.eventId) as number;
    else if (r.thread === root) t = r.ts; // this thread's own receipt on a reply not loaded: its time is the best bound
    else continue; // an unthreaded receipt on an event not loaded says nothing about this thread
    if (t > mark) mark = t;
  }
  for (const r of replies) if (r.sender === me && !r.redacted && r.ts > mark) mark = r.ts;
  let n = 0;
  for (const r of replies) if (r.sender !== me && !r.redacted && r.ts > mark) n++;
  return n;
}

export interface ListThread {
  root: string;
  rootSender: string;
  lastTs: number;
  mine: boolean;
}

/** The Threads list: "all" or "mine" (I wrote the root or replied), newest activity first, ties by root id. */
export function threadList(threads: ListThread[], filter: "all" | "mine", me: string): string[] {
  const keep = threads.filter((t) => filter === "all" || t.mine || t.rootSender === me);
  keep.sort((a, b) => (a.lastTs !== b.lastTs ? b.lastTs - a.lastTs : a.root < b.root ? -1 : a.root > b.root ? 1 : 0));
  return keep.map((t) => t.root);
}

/** Where a main-timeline ("main") receipt may point: the newest event not in a thread, and never a relation whose
 *  target isn't among these events (it may be in a thread). The server refuses a main receipt on a threaded event.
 *  "" = none. */
export function mainReceiptTarget(events: ThreadEv[]): string {
  const ids = threadIds(events);
  const known = new Set(events.map((e) => e.event_id));
  for (let i = events.length - 1; i >= 0; i--) {
    if (ids[i] !== "") continue;
    const tgt = relationTarget(events[i].content);
    if (tgt !== "" && !known.has(tgt)) continue;
    return events[i].event_id;
  }
  return "";
}

/** A message notification's text: "Ana (in thread): …" in a group, "In thread: …" in a DM. */
export function noteText(name: string, text: string, inThread: boolean, isDm: boolean): string {
  if (isDm) return inThread ? `In thread: ${text}` : text;
  return `${name}${inThread ? " (in thread)" : ""}: ${text}`;
}

/** The server's bundled thread aggregation of a root event (`unsigned["m.relations"]["m.thread"]`), or null. The
 *  sender and ts of `latest_event` are readable even while it is still encrypted. Pass the raw (wire) event. */
export function bundleOf(event: Json): Bundle | null {
  const t = event?.unsigned?.["m.relations"]?.[THREAD_REL];
  if (!t || typeof t !== "object" || Array.isArray(t)) return null;
  const lat = t.latest_event;
  if (!lat || typeof lat !== "object" || Array.isArray(lat)) return null;
  const s = (v: unknown) => (typeof v === "string" ? v : "");
  const n = (v: unknown) => (typeof v === "number" && Number.isInteger(v) ? v : 0);
  return { count: n(t.count), latest: { id: s(lat.event_id), sender: s(lat.sender), ts: n(lat.origin_server_ts) }, participated: t.current_user_participated === true };
}

/** The web address of a thread — the shells' push clicks and deep links land here (docs/THREADS.md "Deep link"):
 *  `#/room/<room>[/<event>]?thread=<root>` with encodeURIComponent; an event equal to the root, or empty, is left out.
 *  The router (app/router.ts parseHash) reads it back. Keep this shape stable. */
/** 12.1.16 fix 1-3: what a room coming on screen (or a mention arriving while it is) marks seen in the Mentions list:
 *  the mentions whose own timeline is shown ("" = main, else the thread's root) and that are no newer than `upTo`. A
 *  thread's mention is not seen because the room's main timeline is. (Mark as read stays room-wide; not this rule.)
 *  The desktop's seen_on_attend. */
export function seenOnAttend(mentions: ReadonlyArray<{ e: string; t: number; thread: string }>, shown: readonly string[], upTo: number): string[] {
  return mentions.filter((m) => m.t <= upTo && shown.includes(m.thread)).map((m) => m.e);
}

export function threadLink(room: string, root: string, event: string): string {
  const ev = event && event !== root ? "/" + encodeURIComponent(event) : "";
  return "#/room/" + encodeURIComponent(room) + ev + "?thread=" + encodeURIComponent(root);
}
